const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const cumbreVieja = ee.Geometry.Point([-17.84, 28.57]);
  const funchal = ee.Geometry.Point([-16.91, 32.65]);
  const date = '2021-10-18';

  // 2. Data Acquisition - TROPOMI SO2 data
  const so2Collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_SO2')
    .filterDate(date, ee.Date(date).advance(1, 'day'))
    .select('SO2_column_number_density');

  // Check if collection has data
  const collectionSize = so2Collection.size().getInfo();
  console.log(`SO2 images on ${date}: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get the SO2 image for the date
  const so2Image = so2Collection.first();

  // 3. Extract SO2 values for both locations with buffers
  const bufferDistance = 5000; // 5km buffer

  // Function to extract SO2 mean and count
  function extractSO2Stats(point) {
    const buffer = point.buffer(bufferDistance);
    const stats = so2Image.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: buffer,
      scale: 1000,
      maxPixels: 1e9
    });
    return stats;
  }

  const cumbreStats = extractSO2Stats(cumbreVieja);
  const funchalStats = extractSO2Stats(funchal);

  const cumbreMean = cumbreStats.get('SO2_column_number_density').getInfo();
  const cumbreCount = cumbreStats.get('SO2_column_number_density_count').getInfo();
  const funchalMean = funchalStats.get('SO2_column_number_density').getInfo();
  const funchalCount = funchalStats.get('SO2_column_number_density_count').getInfo();

  console.log(`Cumbre Vieja: SO2=${cumbreMean?.toFixed(6)}, Pixels=${cumbreCount}`);
  console.log(`Funchal: SO2=${funchalMean?.toFixed(6)}, Pixels=${funchalCount}`);

  // 4. Validation checks
  if (cumbreCount === 0 || funchalCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  if (cumbreMean === null || funchalMean === null || 
      isNaN(cumbreMean) || isNaN(funchalMean)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // 5. Final comparison
  console.log(`Difference: ${(cumbreMean - funchalMean).toFixed(6)}`);

  if (cumbreMean > funchalMean) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
